// Mutagen's property manifest (the package's Manifest/Properties.xml, generated by Mutagen's PropertyManifest module, C60
// W6, fixes.20 on): every object's compiled properties in order, which of them Mutagen adds beyond its XML (derived= Break,
// DataType, majorFlag, handWritten, with what each comes from), and where the generated reader reads each value (its data
// subrecord, offset and length). The schema takes these from the manifest instead of applying the generator's rules again.
// Since fixes.24: the offsets of Loqui fields are each field's own (C80), and an object hand-written code makes or enters
// says so (C81: enteredBy="Owner.Name", its fields with filledBy and no offset).
using System.Xml.Linq;

namespace SFSearch.SchemaGen;

public sealed class PropertyManifest
{
    /// <summary>One property (or, with <c>Step</c>, one CustomLogic step) of an object as the manifest lists it.
    /// <c>FilledBy</c> (C81): the hand-written readers that fill it, on a field of an object such code enters.</summary>
    public sealed record Property(string Name, string? Type, string? Derived, string? From, string? Data, int? Offset, int? Length, string? Subrecord, string? Note, bool Step, string? FilledBy);

    readonly Dictionary<string, List<Property>> _objects = new(StringComparer.Ordinal);
    readonly Dictionary<string, string[]> _enteredBy = new(StringComparer.Ordinal);

    /// <summary>
    /// The hand-written readers that make or enter an object (C81, the manifest's <c>enteredBy="Owner.Name[,...]"</c>, a base
    /// class's inherited): a CustomLogic step or Custom field of Owner, or a static method of Owner's class or binary create
    /// translation (<c>APackageTarget.CreateFromBinary</c>). Empty when the generated reader enters it.
    /// </summary>
    public IReadOnlyList<string> EnteredBy(string obj) => _enteredBy.TryGetValue(obj, out var l) ? l : Array.Empty<string>();

    /// <summary>Every object the manifest lists.</summary>
    public IReadOnlyCollection<string> Objects => _objects.Keys;

    /// <summary>An object's properties, in compiled order (empty when the manifest doesn't list it).</summary>
    public IReadOnlyList<Property> Of(string obj) => _objects.TryGetValue(obj, out var l) ? l : Array.Empty<Property>();

    /// <summary>One property of an object's own (not its base's), or null.</summary>
    public Property? Get(string obj, string name) => _objects.TryGetValue(obj, out var l) ? l.FirstOrDefault(p => p.Name == name) : null;

    public static PropertyManifest Load(string file)
    {
        var root = XDocument.Load(file).Root ?? throw new SchemaException($"{file} is empty.");
        if (root.Name.LocalName != "Manifest") throw new SchemaException($"{file} isn't Mutagen's property manifest (its root is {root.Name.LocalName}).");
        var m = new PropertyManifest();
        foreach (var o in root.Elements().Where(e => e.Name.LocalName == "Object"))
        {
            string name = o.Attribute("name")?.Value ?? throw new SchemaException($"{file}: an Object without a name.");
            m._objects[name] = o.Elements().Where(e => e.Name.LocalName is "Property" or "Step").Select(p => new Property(
                p.Attribute("name")!.Value, p.Attribute("type")?.Value, p.Attribute("derived")?.Value, p.Attribute("from")?.Value,
                p.Attribute("data")?.Value, Int(p, "offset"), Int(p, "length"), p.Attribute("subrecord")?.Value, p.Attribute("note")?.Value,
                p.Name.LocalName == "Step", p.Attribute("filledBy")?.Value)).ToList();
            if (o.Attribute("enteredBy")?.Value is { Length: > 0 } by) m._enteredBy[name] = by.Split(',', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries);
        }
        return m;
    }

    static int? Int(XElement e, string name) => e.Attribute(name)?.Value is { } v ? int.Parse(v, System.Globalization.CultureInfo.InvariantCulture) : null;
}
